'use client';

import { useEffect, useId, useLayoutEffect, useRef, useState, useSyncExternalStore, type ReactNode } from 'react';
import { AnimatePresence, motion } from 'motion/react';
import './approval-card.css';

export type ApprovalCardStatus = 'pending' | 'approved' | 'denied';

export interface ApprovalCardProps {
  title: string;
  description?: ReactNode;
  risk?: 'low' | 'medium' | 'high';
  icon?: ReactNode;
  details?: { label: string; value: ReactNode }[];
  preview?: ReactNode;
  children?: ReactNode;
  status?: ApprovalCardStatus;
  defaultStatus?: ApprovalCardStatus;
  onApprove?: (options: { always: boolean }) => void | Promise<unknown>;
  onDeny?: (options: { reason: 'user' | 'timeout' }) => void;
  onEdit?: () => void;
  expiresIn?: number;
  onExpire?: () => void;
  allowAlways?: boolean;
  alwaysLabel?: string;
  approveLabel?: string;
  denyLabel?: string;
  editLabel?: string;
  shortcuts?: boolean;
  label?: ReactNode;
  actions?: 'tray' | 'card';
  className?: string;
}

const reducedQuery = '(prefers-reduced-motion: reduce)';
function subscribeReducedMotion(notify: () => void) {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener('change', notify);
  return () => query.removeEventListener('change', notify);
}
const getReducedMotion = () => window.matchMedia(reducedQuery).matches;
const getServerReducedMotion = () => false;

function Shield() {
  return <svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="m12 3 7 3v5c0 4.5-3.4 7.5-7 10-3.6-2.5-7-5.5-7-10V6l7-3Z" /><path d="m9 12 2 2 4-4" /></svg>;
}

/** UI only: callbacks own the action, and a controlled caller owns its status. */
export function ApprovalCard({
  title, description, risk, icon, details = [], preview, children, status,
  defaultStatus = 'pending', onApprove, onDeny, onEdit, expiresIn, onExpire,
  allowAlways = true, alwaysLabel = 'Always allow this action', approveLabel = 'Approve',
  denyLabel = 'Deny', editLabel = 'Edit', shortcuts = true, label, actions = 'tray', className = '',
}: ApprovalCardProps) {
  const id = useId();
  const [localStatus, setLocalStatus] = useState(defaultStatus);
  const currentStatus = status ?? localStatus;
  const [always, setAlways] = useState(false);
  const [busy, setBusy] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [announcement, setAnnouncement] = useState('');
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState(false);
  const duration = expiresIn === undefined ? undefined : Math.max(0, expiresIn * 1000);
  const [seconds, setSeconds] = useState(() => Math.ceil((duration ?? 0) / 1000));
  const [resolvedAt, setResolvedAt] = useState<Date | null>(null);
  const [height, setHeight] = useState<number>();
  const root = useRef<HTMLDivElement>(null);
  const content = useRef<HTMLDivElement>(null);
  const pending = useRef<HTMLDivElement>(null);
  const resolved = useRef<HTMLDivElement>(null);
  const focusInside = useRef(false);
  const previousStatus = useRef(currentStatus);
  const request = useRef({ generation: 0, locked: false });
  const clock = useRef({ remaining: duration ?? 0, startedAt: null as number | null });
  const latest = useRef({ onApprove, onDeny, onExpire, status: currentStatus, controlled: status !== undefined });
  latest.current = { onApprove, onDeny, onExpire, status: currentStatus, controlled: status !== undefined };
  const reduceMotion = useSyncExternalStore(subscribeReducedMotion, getReducedMotion, getServerReducedMotion);
  const blocked = busy || submitted;

  function stopClock() {
    if (clock.current.startedAt !== null) {
      clock.current.remaining = Math.max(0, clock.current.remaining - (performance.now() - clock.current.startedAt));
      clock.current.startedAt = null;
    }
  }

  // Invalidates an in-flight callback when this request is unmounted/replaced.
  useEffect(() => () => { request.current.generation += 1; }, []);

  useLayoutEffect(() => {
    if (previousStatus.current === currentStatus) return;
    previousStatus.current = currentStatus;
    request.current.generation += 1;
    request.current.locked = currentStatus !== 'pending';
    setBusy(false);
    setSubmitted(false);
    setError(null);
    if (currentStatus === 'pending') {
      setAlways(false);
      setAnnouncement('');
      setResolvedAt(null);
    } else {
      setResolvedAt(new Date());
      setAnnouncement(`${currentStatus === 'approved' ? 'Approved' : 'Denied'}: ${title}`);
      // React may already have removed the active button; the focus ref survives it.
      if (focusInside.current) resolved.current?.focus({ preventScroll: true });
    }
    // AnimatePresence keeps the old visual layer briefly; it is no longer interactive.
    if (pending.current) {
      pending.current.inert = currentStatus !== 'pending';
      if (currentStatus === 'pending') pending.current.removeAttribute('aria-hidden');
      else pending.current.setAttribute('aria-hidden', 'true');
    }
  }, [currentStatus, title]);

  useLayoutEffect(() => {
    stopClock();
    clock.current.remaining = duration ?? 0;
    setSeconds(Math.ceil((duration ?? 0) / 1000));
  }, [currentStatus, duration]);

  useLayoutEffect(() => {
    const node = content.current;
    if (!node) return;
    const measure = () => setHeight(node.getBoundingClientRect().height);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(node);
    return () => observer.disconnect();
  }, [currentStatus]);

  function finish(next: ApprovalCardStatus) {
    setSubmitted(true);
    if (!latest.current.controlled) setLocalStatus(next);
  }

  function deny(reason: 'user' | 'timeout') {
    if (latest.current.status !== 'pending' || request.current.locked) return;
    request.current.locked = true;
    stopClock();
    if (reason === 'timeout') latest.current.onExpire?.();
    latest.current.onDeny?.({ reason });
    finish('denied');
  }

  async function approve() {
    if (latest.current.status !== 'pending' || request.current.locked) return;
    request.current.locked = true;
    stopClock();
    const generation = request.current.generation;
    setError(null);
    setBusy(true);
    try {
      await latest.current.onApprove?.({ always: allowAlways && always });
      if (request.current.generation === generation && latest.current.status === 'pending') finish('approved');
    } catch (cause) {
      if (request.current.generation !== generation || latest.current.status !== 'pending') return;
      request.current.locked = false;
      setError(cause instanceof Error && cause.message ? cause.message : typeof cause === 'string' && cause ? cause : 'Approval failed. Please try again.');
    } finally {
      if (request.current.generation === generation) setBusy(false);
    }
  }

  useEffect(() => {
    if (currentStatus !== 'pending' || duration === undefined || hovered || focused || blocked) return;
    clock.current.startedAt = performance.now();
    const tick = () => {
      const remaining = Math.max(0, clock.current.remaining - (performance.now() - (clock.current.startedAt ?? performance.now())));
      setSeconds(Math.ceil(remaining / 1000));
      if (remaining === 0) deny('timeout');
    };
    tick();
    const timer = window.setInterval(tick, 100);
    return () => { window.clearInterval(timer); stopClock(); };
  }, [currentStatus, duration, hovered, focused, blocked]);

  const previewContent = preview !== undefined ? preview : children;
  const descriptionIds = [currentStatus === 'pending' && description != null && `${id}-description`, currentStatus === 'pending' && duration !== undefined && `${id}-countdown`, error && `${id}-error`].filter(Boolean).join(' ') || undefined;
  const alwaysCheckbox = allowAlways && <label className="approval-card__always">
      <input type="checkbox" checked={always} aria-disabled={blocked}
        onClick={event => { if (request.current.locked) event.preventDefault(); }}
        onChange={event => { if (!request.current.locked) setAlways(event.target.checked); }} />
      <span>{alwaysLabel}</span>
    </label>;
  const actionRow = <div className="approval-card__actions">
    {actions === 'card' && alwaysCheckbox}
    {duration !== undefined && <span className="approval-card__clock" data-urgent={seconds <= 10} aria-hidden="true">Expires in {Math.floor(seconds / 60)}:{String(seconds % 60).padStart(2, '0')}</span>}
    <div className="approval-card__buttons">
      {onEdit && <button type="button" className="approval-card__button" aria-disabled={blocked} onClick={() => { if (!request.current.locked) onEdit(); }}>{editLabel}</button>}
      <button type="button" className="approval-card__button" aria-disabled={blocked} aria-keyshortcuts="Escape" onClick={() => deny('user')}>{denyLabel}{shortcuts && <kbd aria-hidden="true">Esc</kbd>}</button>
      <button type="button" className="approval-card__button approval-card__button--approve" aria-disabled={blocked} aria-label={busy ? `${approveLabel} (processing)` : undefined} aria-keyshortcuts="Meta+Enter Control+Enter" onClick={() => void approve()}>
        {approveLabel}{busy ? <span className="approval-card__spinner" aria-hidden="true" /> : shortcuts && <kbd aria-hidden="true">⌘↵</kbd>}
      </button>
    </div>
  </div>;

  return <div ref={root} className={`approval-card ${className}`} data-status={currentStatus} data-actions={actions} data-reduced-motion={reduceMotion}>
    <motion.div className="approval-card__morph" animate={{ height: height ?? 'auto' }} transition={{ duration: reduceMotion ? 0 : 0.52, ease: [0.22, 1, 0.36, 1] }}>
      <div ref={content} className="approval-card__content" role="group" aria-labelledby={`${id}-${currentStatus === 'pending' ? 'title' : 'resolved-title'}`} aria-describedby={descriptionIds} aria-busy={busy}
        onMouseEnter={() => { stopClock(); setHovered(true); }}
        onMouseLeave={() => setHovered(false)}
        onFocusCapture={() => { stopClock(); focusInside.current = true; setFocused(true); }}
        onBlurCapture={event => {
          if (!event.currentTarget.contains(event.relatedTarget as Node | null)) { focusInside.current = false; setFocused(false); }
        }}
        onKeyDown={event => {
          if (currentStatus !== 'pending' || event.nativeEvent.isComposing) return;
          if (event.key === 'Enter' && (event.metaKey || event.ctrlKey)) { event.preventDefault(); event.stopPropagation(); void approve(); }
          if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); deny('user'); }
        }}>
        <AnimatePresence mode="popLayout">
        {currentStatus === 'pending' ? <motion.div key="pending" ref={pending} className="approval-card__pending"
          initial={reduceMotion ? false : { opacity: 0, y: 6, filter: 'blur(5px)' }}
          animate={{ opacity: 1, y: 0, filter: 'blur(0px)' }}
          exit={{ opacity: 0, y: -6, scale: 0.985, filter: 'blur(2px)', transition: { duration: reduceMotion ? 0 : 0.28, ease: [0.22, 1, 0.36, 1] } }}
          transition={{ duration: reduceMotion ? 0 : 0.35, ease: [0.22, 1, 0.36, 1] }}>
          {label != null && <div className="approval-card__label">{label}</div>}
          <div className="approval-card__surface">
            <div className="approval-card__header">
              <span className="approval-card__icon">{icon ?? <Shield />}</span>
              <div className="approval-card__heading"><span id={`${id}-title`} className="approval-card__title">{title}</span>
                {description != null && <div id={`${id}-description`} className="approval-card__description">{description}</div>}
              </div>
              {risk && <span className="approval-card__risk" data-risk={risk}><span className="approval-card__risk-dot" aria-hidden="true" /><span>{risk[0].toUpperCase() + risk.slice(1)}</span><span className="approval-card__risk-word"> risk</span></span>}
            </div>
            {(previewContent != null || details.length > 0) && <div className="approval-card__preview">
              {previewContent != null && <div className="approval-card__custom-preview">{previewContent}</div>}
              {details.length > 0 && <dl className="approval-card__details">{details.map((detail, index) => <div key={index}><dt>{detail.label}</dt><dd>{detail.value}</dd></div>)}</dl>}
            </div>}
            {error && <p className="approval-card__error" role="alert" id={`${id}-error`}>{error}</p>}
            {actions === 'tray' && alwaysCheckbox}
            {actions === 'card' && actionRow}
          </div>
          {actions === 'tray' && actionRow}
          {duration !== undefined && <span id={`${id}-countdown`} className="approval-card__sr-only">Expires in {seconds} seconds unless approved or denied. Countdown pauses while hovered, focused, or approving.</span>}
        </motion.div> : <motion.div key="resolved" ref={resolved} tabIndex={-1} className="approval-card__resolved"
          initial={reduceMotion ? false : { opacity: 0, y: 4, filter: 'blur(2px)' }} animate={{ opacity: 1, y: 0, filter: 'blur(0px)' }}
          exit={{ opacity: 0, filter: 'blur(4px)', transition: { duration: reduceMotion ? 0 : 0.12 } }}
          transition={{ duration: reduceMotion ? 0 : 0.42, delay: reduceMotion ? 0 : 0.12, ease: [0.22, 1, 0.36, 1] }}>
          <motion.span className="approval-card__decision-icon" aria-hidden="true" initial={reduceMotion ? false : { opacity: 0, scale: 0.5 }} animate={{ opacity: 1, scale: 1 }} transition={{ duration: reduceMotion ? 0 : 0.46, delay: reduceMotion ? 0 : 0.14, ease: [0.22, 1, 0.36, 1] }}><svg viewBox="0 0 20 20" fill="none"><motion.path key={currentStatus} d={currentStatus === 'approved' ? 'm5 10 3 3 7-7' : 'm6 6 8 8M14 6l-8 8'} initial={{ pathLength: reduceMotion ? 1 : 0 }} animate={{ pathLength: 1 }} transition={{ duration: reduceMotion ? 0 : .42, delay: reduceMotion ? 0 : .3, ease: [.22, 1, .36, 1] }} /></svg></motion.span>
          <span id={`${id}-resolved-title`} className="approval-card__resolved-title">{title}</span>
          <span className="approval-card__decision">{currentStatus === 'approved' ? 'Approved' : 'Denied'}<time dateTime={resolvedAt?.toISOString()} className="approval-card__resolved-time"> · just now</time></span>
        </motion.div>}
        </AnimatePresence>
      </div>
    </motion.div>
    <span className="approval-card__sr-only" role="status" aria-live="polite" aria-atomic="true">{announcement}</span>
  </div>;
}

.approval-card {
  --approval-bg: #fff;
  --approval-tray: #f0f0f0;
  --approval-preview: #fafafa;
  --approval-icon: #f4f4f4;
  --approval-text: #171717;
  --approval-muted: #6b6b6b;
  --approval-faint: #8a8a8a;
  --approval-line: #ececec;
  --approval-primary: #171717;
  --approval-on-primary: #fff;
  --approval-focus: #5b7ac7;
  color: var(--approval-muted);
  font-family: Inter, 'Inter Variable', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 13px;
  font-weight: 400;
  line-height: 1.45;
  letter-spacing: -0.078px;
  width: 100%;
  min-width: 0;
  container: approval / inline-size;
  position: relative;
  text-align: left;
  -webkit-font-smoothing: antialiased;
}
.approval-card *, .approval-card *::before, .approval-card *::after { box-sizing: border-box; }
.approval-card__morph { overflow: hidden; border-radius: 20px; background: var(--approval-tray); }
.approval-card__content { position: relative; padding: 4px; }
.approval-card__pending { transform-origin: top center; }
.approval-card:not([data-status='pending']) .approval-card__pending { pointer-events: none; }
.approval-card__surface { background: var(--approval-bg); border: 0; border-radius: 16px; padding: 16px; box-shadow: 0 0 0 1px var(--approval-line), 0 1px 2px #0000000a; }
.approval-card__header { display: flex; align-items: flex-start; gap: 12px; min-width: 0; }
.approval-card__icon { flex: 0 0 32px; width: 32px; height: 32px; display: grid; place-items: center; color: var(--approval-text); background: var(--approval-icon); border-radius: 9px; box-shadow: inset 0 0 0 1px var(--approval-line); }
.approval-card__icon svg { width: 16px; height: 16px; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
.approval-card__heading { flex: 1; min-width: 0; padding-top: 1px; }
.approval-card__title { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--approval-text); font-weight: 550; font-size: 14px; line-height: 20px; letter-spacing: -0.154px; }
.approval-card__description { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--approval-muted); font-size: 13px; line-height: 18px; margin-top: 1px; }
.approval-card__risk { display: flex; align-items: center; gap: 6px; flex: none; height: 22px; margin-top: 1px; padding: 0 9px 0 8px; border-radius: 999px; font-size: 12px; font-weight: 500; line-height: 12px; white-space: nowrap; background: #f0f0f0; color: #626262; }
.approval-card__risk-dot { opacity: .8; width: 6px; height: 6px; border-radius: 50%; background: currentColor; flex: none; }
.approval-card__risk[data-risk='medium'] { min-width: 104.609375px; background: #fbf3e2; color: #8a5a00; }
.approval-card__risk[data-risk='high'] { background: #fff0ef; color: #a83a32; }
.approval-card__preview { display: grid; gap: 12px; margin-top: 14px; padding: 12px; border-radius: 10px; background: var(--approval-preview); box-shadow: inset 0 0 0 1px var(--approval-line); }
.approval-card__custom-preview { min-width: 0; }
.approval-card__details { margin: 0; display: grid; grid-template-columns: minmax(0, max-content) minmax(0, 1fr); gap: 6px 16px; }
.approval-card__custom-preview + .approval-card__details { border-top: 1px solid var(--approval-line); padding-top: 12px; }
.approval-card__details > div { display: contents; }
.approval-card__details dt { color: var(--approval-faint); overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.approval-card__details dd { margin: 0; min-width: 0; color: var(--approval-text); overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.approval-card__actions { display: flex; align-items: center; gap: 6px 12px; flex-wrap: wrap; min-height: 44px; padding: 6px 2px 2px 10px; }
.approval-card[data-actions='card'] .approval-card__surface > .approval-card__actions { margin-top: 16px; padding: 14px 0 0; border-top: 1px solid var(--approval-line); }
.approval-card__always { display: flex; align-items: flex-start; gap: 8px; min-width: 0; margin-top: 14px; color: var(--approval-muted); font-size: 13px; cursor: pointer; }
.approval-card__actions .approval-card__always { margin-top: 0; }
.approval-card__always input { appearance: none; position: relative; margin: 1.5px 0 0; width: 16px; height: 16px; flex: 0 0 16px; border: 1px solid #b8b8b8; border-radius: 5px; background: var(--approval-bg); cursor: pointer; }
.approval-card__always input:checked { background: var(--approval-primary); border-color: var(--approval-primary); }
.approval-card__always input:checked::after { content: ''; position: absolute; left: 4px; top: 1px; width: 5px; height: 9px; border: solid var(--approval-on-primary); border-width: 0 1.5px 1.5px 0; transform: rotate(45deg); }
.approval-card__always input[aria-disabled='true'] { cursor: wait; }
.approval-card__buttons { display: flex; align-items: center; gap: 4px; margin-left: auto; }
.approval-card__button { appearance: none; border: 0; border-radius: 10px; background: transparent; color: var(--approval-text); font-family: inherit; font-size: 13px; font-weight: 500; line-height: 13px; letter-spacing: normal; padding: 0 8px 0 12px; height: 34px; display: inline-flex; align-items: center; justify-content: center; gap: 8px; white-space: nowrap; cursor: pointer; transition: background-color 160ms ease, box-shadow 160ms ease, transform 160ms cubic-bezier(0.22, 1, 0.36, 1), opacity 160ms ease; }
.approval-card__button:hover:not([aria-disabled='true']) { background: var(--approval-tray); }
.approval-card__button--approve { background: var(--approval-primary); color: var(--approval-on-primary); box-shadow: 0 1px 2px #0000001f; }
.approval-card__button--approve:hover:not([aria-disabled='true']) { background: var(--approval-primary); opacity: 0.84; }
.approval-card__button[aria-disabled='true'] { cursor: wait; opacity: 0.65; }
.approval-card__button--approve[aria-disabled='true'] { opacity: 1; }
.approval-card__content[aria-busy='true'] .approval-card__always { opacity: 0.5; }
.approval-card__button kbd { display: grid; place-items: center; height: 20px; font-family: inherit; font-size: 11px; line-height: 11px; font-weight: 500; color: var(--approval-faint); background: #0000000e; padding: 0 5px; border-radius: 6px; }
.approval-card__button--approve kbd { background: #ffffff24; color: #ffffffb8; }
.approval-card__button:focus-visible, .approval-card__always input:focus-visible, .approval-card__resolved:focus-visible { outline: 2px solid var(--approval-focus); outline-offset: 2px; }
.approval-card__clock { font-size: 11px; color: var(--approval-muted); white-space: nowrap; }
.approval-card__clock[data-urgent='true'] { color: #9b6a12; }
.approval-card__label { padding: 10px 16px 8px; color: var(--approval-muted); font-size: 11px; }
.approval-card__error { font-size: 12px; line-height: 18px; margin: 12px 0 0; color: #ad352d; overflow-wrap: anywhere; }
.approval-card__spinner { display: grid; place-items: center; width: 20px; height: 20px; }
.approval-card__spinner::after { content: ''; width: 12px; height: 12px; border-radius: 50%; border: 1.5px solid currentColor; border-right-color: transparent; animation: approval-spin 700ms linear infinite; }
.approval-card__resolved { display: flex; align-items: center; gap: 10px; padding: 12px 14px; min-height: 48px; border-radius: 16px; background: var(--approval-bg); box-shadow: 0 0 0 1px var(--approval-line), 0 1px 2px #0000000a; }
.approval-card__decision-icon { display: grid; place-items: center; flex: 0 0 22px; width: 22px; height: 22px; border-radius: 50%; color: #1a7f45; background: #e9f6ee; }
.approval-card__decision-icon svg { width: 14px; height: 14px; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.approval-card[data-status='denied'] .approval-card__decision-icon { background: #f2f2f2; color: var(--approval-muted); }
.approval-card__resolved-title { flex: 1; min-width: 0; color: var(--approval-text); font-size: 13.5px; font-weight: 500; line-height: 1.45; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.approval-card__decision { flex: none; font-size: 13px; white-space: nowrap; color: var(--approval-faint); }
.approval-card__resolved-time { font: inherit; }
.approval-card__sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
:where(.dark, [data-theme='dark']) .approval-card, .approval-card:where(.dark, [data-theme='dark']) { --approval-bg: #202020; --approval-tray: #292929; --approval-preview: #252525; --approval-icon: #292929; --approval-text: #ededed; --approval-muted: #a2a2a2; --approval-faint: #999; --approval-line: #353535; --approval-primary: #ededed; --approval-on-primary: #171717; --approval-focus: #95b1fb; }
:where(.dark, [data-theme='dark']) .approval-card__risk[data-risk='low'] { background: #333; color: #bbb; }
:where(.dark, [data-theme='dark']) .approval-card__risk[data-risk='medium'] { background: #3a301c; color: #edc779; }
:where(.dark, [data-theme='dark']) .approval-card__risk[data-risk='high'] { background: #432724; color: #f2a39b; }
:where(.dark, [data-theme='dark']) .approval-card__error { color: #f2a39b; }
:where(.dark, [data-theme='dark']) .approval-card__clock[data-urgent='true'] { color: #edc779; }
:where(.dark, [data-theme='dark']) .approval-card__button--approve kbd { background: #00000014; color: #555; }
:where(.dark, [data-theme='dark']) .approval-card__decision-icon { background: #263b2d; color: #a3d4b3; }
:where(.dark, [data-theme='dark']) .approval-card[data-status='denied'] .approval-card__decision-icon { background: var(--approval-tray); color: var(--approval-muted); }
@container approval (width < 400px) {
  .approval-card__buttons { width: 100%; }
  .approval-card__buttons > button { flex: 1; }
  .approval-card__button kbd { display: none; }
  .approval-card__clock { margin-left: auto; }
}
@container approval (width < 340px) {
  .approval-card__risk-word, .approval-card__resolved-time { display: none; }
  .approval-card__risk[data-risk='medium'] { min-width: 0; }
  .approval-card__header { gap: 9px; }
  .approval-card__surface { padding: 14px; }
}
@media (hover: none) { .approval-card__button kbd { display: none; } }
@media (prefers-reduced-motion: reduce) {
  .approval-card__button { transition: none; }
  .approval-card__spinner::after { animation: none; }
}
@keyframes approval-spin { to { transform: rotate(360deg); } }
